 const au=$("#auto",el);if(au)au.onchange=()=>{o.auto=au.checked};const fo=$("#follow",el);if(fo)fo.onchange=()=>{o.follow=fo.checked};
 $$("[data-cur]",el).forEach(b=>b.onclick=()=>{Player.stop();o.cur=+b.dataset.cur;o.hidden=o.mode==="recall";upd()});
