  if(A.state==="aku-bisa"){if(!A.due){A.interval=1;A.due=addDays(today(),1);dayRec().hafal++;addStar(1,"Ayat baru dipelajari");}sparkle();guide("MasyaAllah, hebat!")}else{A.interval=1;A.due=addDays(today(),1);guide("Tidak apa-apa, kita latihan lagi ya")}
