/* ===== 5. murajaah ===== */
const STEPS=[1,3,7,14,30];
function vMurajaah(){return back()+`<h1>My Murajaah 🔁</h1><p class="sub">Mengulang hafalan supaya tetap kuat.</p><div id="mj">${loadingBox()}</div>`}
async function aMurajaah(){const el=$("#mj");const due=dueList();const up=[];for(const [s,h] of Object.entries(PR.hafal))for(const [a,x] of Object.entries(h.ayat||{}))if(x.due&&x.due>today())up.push([+s,+a,x.due]);up.sort((x,y)=>x[2].localeCompare(y[2]));
 if(!due.length){el.innerHTML=`<div class="card center"><div class="moon">🌷</div><h2>Tidak ada murajaah untuk hari ini</h2><p>MasyaAllah! Kamu bisa menghafal ayat baru atau membaca Al-Qur’an.</p><button class="btn mint" data-go="hafalList">Hafalan baru</button></div>${up.length?`<div class="card"><h3>Jadwal berikutnya</h3><ul class="plain">${up.slice(0,8).map(([s,a,d])=>`<li>${esc(SURAH(s).latin)} ayat ${a} <span class="tiny">· ${new Date(d+"T12:00").toLocaleDateString("id-ID",{weekday:"long",day:"numeric",month:"short"})}</span></li>`).join("")}</ul></div>`:""}<p class="tiny">Jadwal: hari berikutnya, lalu 3 hari, 1 minggu, 2 minggu, dan sebulan kemudian. Ini panduan latihan, bukan jaminan hafalan sudah kuat.</p>`;return}
 const i=App.p.i||0;const [s,a]=due[Math.min(i,due.length-1)];let rec;try{rec=await QuranSource.load(s)}catch(e){el.innerHTML=errorBox(e);$("[data-retry]",el).onclick=()=>go("murajaah",App.p);return}if(App.view!=="murajaah")return;
 const x=rec.ayat.find(y=>y.a===a);const hidden=App.p.hidden!==false;
 el.innerHTML=`<div class="card"><p class="tiny">Today’s Murajaah · ${Math.min(i,due.length-1)+1} dari ${due.length}</p><div class="bar"><i style="width:${100*(i)/due.length}%"></i></div></div>
 <article class="ayah big ${hidden?"hidden":""}"><div class="ahead"><span class="anum">${a}</span><b>${esc(SURAH(s).latin)}</b></div><p class="ar" lang="ar" dir="rtl">${hidden?`<span class="veil">🙈 Coba ucapkan ayatnya dulu…</span>`:esc(x.ar)}</p></article>
 <div class="row center"><button class="btn lav" data-pl>▶ Dengarkan</button><button class="btn ghost" data-sh>${hidden?"👀 Lihat teks":"🙈 Sembunyikan"}</button></div>
 <div class="card selfcheck"><b>Bagaimana tadi?</b><div class="row"><button class="btn pink" data-r="hard">🌱 Masih sulit</button><button class="btn mint" data-r="ok">🌸 Lancar</button></div><p class="tiny">“Masih sulit” akan diulang besok. “Lancar” diulang lagi beberapa hari kemudian.</p></div>`;
 $("[data-pl]",el).onclick=()=>Player.play([{s,a}],{repeat:1});$("[data-sh]",el).onclick=()=>{App.p.hidden=!hidden;aMurajaah()};
 $$("[data-r]",el).forEach(b=>b.onclick=()=>{const A=PR.hafal[s].ayat[a];if(b.dataset.r==="ok"){const idx=STEPS.indexOf(A.interval||1);A.interval=STEPS[Math.min(STEPS.length-1,idx+1)]}else A.interval=1;A.due=addDays(today(),A.interval);A.last=today();A.mur=(A.mur||0)+1;dayRec().mur++;saveProg();
  if(Math.min(i+1,due.length)>=due.length||dueList().length===0){PR.sessions.murajaah++;addStar(2,"Murajaah selesai");sparkle();guide("MasyaAllah, terima kasih sudah murajaah hari ini!");App.p={};aMurajaah()}else{App.p={i:0,hidden:true};aMurajaah()}})}

/* ===== 6. Iqra ===== */
