 const pr=PR.iqra[j]=PR.iqra[j]||{seen:{}};pr.last=pg;if(!pr.seen[pg]){pr.seen[pg]=today();dayRec().iqra++;if(Object.keys(pr.seen).length%3===0)addStar(1,"Halaman Iqra")}saveProg();
 const url=URL.createObjectURL(page.blob);const aud=page.audio?URL.createObjectURL(page.audio):null;
