  $("#iimp").onclick=async()=>{const j=+$("#ij").value,fs=[...$("#if").files],src=$("#isrc").value.trim();if(!fs.length||!src){toast("Pilih gambar dan isi sumber & izin.");return}fs.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));const have=keys.filter(k=>String(k).startsWith(j+":")).length;for(let i=0;i<fs.length;i++)await IDB.put("iqra",j+":"+(have+i+1),{blob:fs[i],source:src,added:today()});toast(`${fs.length} halaman diimpor.`);go("parent",{tab:"iqra"})};
